38	const VERT = /* glsl */ `
39	uniform mat4 uProjVP;
40	varying vec4 vProj;
41	varying vec3 vW;
42	varying vec3 vN;
43	void main() {
44	  vec4 wp = modelMatrix * vec4(position, 1.0);
45	  vProj = uProjVP * wp;
46	  vW = wp.xyz;
47	  vN = normalize(mat3(modelMatrix) * normal);
48	  gl_Position = projectionMatrix * viewMatrix * wp;
49	}`;
50	
51	const FRAG = /* glsl */ `
52	uniform sampler2D uPlate;
53	uniform sampler2D uDepth;
54	uniform float uUseDepth;
55	uniform vec2 uNearFar;
56	uniform vec3 uFallback;
57	uniform sampler2D uPatch;   // material patch cut from the approved artwork (wall slots / gold band / towel)
58	uniform float uPatchK;      // patch repeats per world unit
59	uniform vec3 uProjPos;      // projector (approved view) position
60	uniform vec4 uPjPost;
61	uniform vec2 uPjRes;
62	uniform sampler2D uFill;    // m08fill: world-anchored wall tile cut from the picture's near pipe wall (unwrap08.py)
63	uniform float uFillMode;    // 0 off (triplanar patch), 1 drum wall (around the chamber axis), 2 flat disc (x/y)
64	uniform vec2 uFillSize;     // tile size in world units (around, along)
65	uniform vec3 uDrum;         // chamber axis x, y and radius
66	uniform mat4 uProjVP;
67	uniform float uSwim;        // m08swim (floor only): the painted river's banks spread to cover Benny's whole swim lane
68	uniform sampler2D uRiv;     // 64 x 1: painted river centre x (r) and full width (g) along z
69	uniform vec4 uRivZ;         // z at texel 0, z at texel 63, lane half-width to cover, floor y
70	uniform sampler2D uOcc;     // m08occ (door wall only): plate with towel + platform painted out (occ08.py), alpha = usable
71	uniform float uOccOn;
72	uniform sampler2D uTMask;   // m08towelm (towel only): the painted towel's outline in plate coordinates (towelmask08.py)
73	uniform float uTMaskOn;
74	uniform vec4 uClipIn;       // m08far collar only: discard inside this x/y circle (the chamber's cross-section) ...
75	uniform vec4 uClipOut;      // ... and outside this one (the pushed arch's outline); w > 0.5 = on
76	uniform vec4 uCeil;         // m08ceil (door wall only): painted door centre x, y on the door plane, plane z, w > 0.5 = on
77	uniform vec4 uCeilW;        // m08ceil source window: angle start, angle width (rad), radius band start, end (world u)
78	uniform sampler2D uNearT;   // m08near (floor only): crisp near-river tile from the approved picture's own near band (near08.py)
79	uniform vec4 uNear;         // z at tile v = 0, world length of one tile period along the river, tile lateral half range A, w > 0.5 = on
80	uniform vec4 uNearM;        // projection magnification ramp start / end, lateral fade start / end (|lane position|, 1 = bank)
81	uniform vec2 uNearC;        // tile a of the lane centre and of the half lane (the painted water incl. foam spans c +- h)
82	uniform vec4 uCup;          // m08cup (spout cups only): cup centre xyz, w > 0.5 = on
83	uniform vec3 uCupM;         // m08cup mirror plane normal (horizontal, perpendicular to the projector's view of the cup)
84	varying vec4 vProj;
85	varying vec3 vW;
86	varying vec3 vN;
87	${PROJ05_INVERSE}
88	// triplanar, mirrored-repeat sampling of the patch: surfaces the approved picture never showed (or showed edge-on)
89	vec3 patchColor() {
90	  vec3 n = abs(normalize(vN)); n /= max(n.x + n.y + n.z, 1e-4);
91	  vec3 p = vW * uPatchK;
92	  return texture2D(uPatch, p.zy).rgb * n.x + texture2D(uPatch, p.xz).rgb * n.y + texture2D(uPatch, p.xy).rgb * n.z;
93	}
94	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
95	vec3 fillColor() {
96	  vec2 q;
97	  if (uFillMode < 1.5) {
98	    // angle from straight down: the wrap of atan lies under the floor, never seen
99	    float a = atan(vW.x - uDrum.x, -(vW.y - uDrum.y));
100	    float n = floor(6.2831853 * uDrum.z / uFillSize.x + 0.5);  // whole tiles around the drum: no seam
101	    q = vec2(a / 6.2831853 * n, vW.z / uFillSize.y);
102	  } else q = vW.xy / uFillSize;
103	  return texture2D(uFill, q).rgb;
104	}
105	// m08ceil: the painted end wall is concentric around the door (chrome rim, gold bulb ring, slot rows), so a door-wall point
106	// the approved view could not see (behind the arch ring: the ceiling above the door) takes the user's pixels from the SAME
107	// radius in a clean window of the painted wall beside the door (left of the door, between the spout cup and its stream),
108	// repeated (mirrored, a whole number of times around) by angle; beyond the window's slot band the slot rows repeat outward.
109	// The rings therefore continue across the old seam instead of meeting a generic tile.
110	vec3 ceilColor() {
111	  vec2 d = vW.xy - uCeil.xy;
112	  float r = length(d), a = atan(d.y, d.x);
113	  float fu = mod((a - uCeilW.x) / uCeilW.y, 2.0);
114	  float as = uCeilW.x + (fu < 1.0 ? fu : 2.0 - fu) * uCeilW.y;
115	  float rs = r;
116	  if (r > uCeilW.w) { float w2 = uCeilW.w - uCeilW.z, fr = mod(r - uCeilW.w, 2.0 * w2); rs = fr < w2 ? uCeilW.w - fr : uCeilW.z + (fr - w2); }
117	  vec4 q = uProjVP * vec4(uCeil.xy + rs * vec2(cos(as), sin(as)), uCeil.z, 1.0);
118	  return texture2D(uPlate, q.xy / q.w * 0.5 + 0.5).rgb;
119	}
120	vec2 riv(float z) {
121	  float f = clamp((z - uRivZ.x) / (uRivZ.y - uRivZ.x), 0.0, 1.0) * 63.0;
122	  float i0 = floor(f);
123	  vec2 a = texture2D(uRiv, vec2((i0 + 0.5) / 64.0, 0.5)).rg, b = texture2D(uRiv, vec2((min(i0 + 1.0, 63.0) + 0.5) / 64.0, 0.5)).rg;
124	  return mix(a, b, f - i0);
125	}
126	// m08swim: lateral remap of a floor point. The middle of the painted river stays as painted, its banks (water edge,
127	// foam) are spread out to the lane half-width, the floor beyond is pushed out and eased back over 2.5 u. World-anchored
128	// (depends on the floor point only) and faded in with the camera's distance from the approved viewpoint.
129	vec3 swimRemap(vec3 w, float mv) {
130	  vec2 r = riv(w.z);
131	  float hp = 0.5 * r.y, h = mix(hp, max(hp, uRivZ.z), mv);
132	  if (h <= hp + 1e-3) return w;
133	  float d = w.x - r.x, ad = abs(d), a = 0.45 * hp, e = h - hp, o;
134	  if (ad <= a) o = ad;
135	  else if (ad <= h) o = a + (ad - a) * (hp - a) / (h - a);
136	  else o = ad - e * max(0.0, 1.0 - (ad - h) / 2.5);
137	  return vec3(r.x + sign(d) * o, w.y, w.z);
138	}
139	void main() {
140	  if (uClipIn.w > 0.5 && (distance(vW.xy, uClipIn.xy) < uClipIn.z || distance(vW.xy, uClipOut.xy) > uClipOut.z)) discard;
141	  // m08towelm: the towel proxy is cut to the painted towel's outline (the depth bake does the same, so the door wall
142	  // behind receives the window pixels that the rectangle used to carry at towel depth)
143	  if (uTMaskOn > 0.5 && vProj.w > 0.0 && texture2D(uTMask, vProj.xy / vProj.w * 0.5 + 0.5).r < 0.5) discard;
144	  // m08fill fades in as the camera leaves the approved viewpoint (the approved view keeps its exact old pixels)
145	  vec3 pc = patchColor();
146	  if (uFillMode > 0.5) pc = mix(pc, fillColor(), smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
147	  if (uCeil.w > 0.5) pc = mix(pc, ceilColor(), smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
148	  vec3 t = pc;
149	  // stretch guard: the projection is used where the current view sees the surface no more face-on than the approved
150	  // view did (ratio of the two incidence cosines); in the approved view itself the ratio is 1 -> pure projection
151	  vec3 nn = normalize(vN);
152	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
153	  float keep = 1.0 - smoothstep(2.5, 6.0, cc / max(cp, 1e-3));
154	  vec4 pj = vProj;
155	  float pw = 0.0;  // weight of the direct projection in t (m08cup fills the rest from the cup's mirrored side)
156	  if (uSwim > 0.5) {
157	    float ms = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
158	    if (ms > 0.0) pj = uProjVP * vec4(swimRemap(vW, ms), 1.0);
159	  }
160	  if (pj.w > 0.0) {
161	    vec3 ndc = pj.xyz / pj.w;
162	    vec2 uv = ndc.xy * 0.5 + 0.5;
163	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
164	      float vis = 1.0;
165	      if (uUseDepth > 0.5) {
166	        float zf = linZ(ndc.z * 0.5 + 0.5);
167	        float zs = linZ(texture2D(uDepth, uv).r);
168	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
169	        // m08fill: once the camera has left the approved viewpoint, a soft hand-over to the fill (5 x 5 taps over ~3 %
170	        // of the frame) instead of a hard shadow line; at the viewpoint itself the exact single-tap test (view unchanged)
171	        float mv = uFillMode > 0.5 ? smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)) : 0.0;
172	        if (mv > 0.0) {
173	          float sv = 0.0;
174	          for (int i = -2; i <= 2; i++) for (int j = -2; j <= 2; j++) {
175	            float zt = linZ(texture2D(uDepth, uv + vec2(float(i), float(j) * 0.5625) * 0.007).r);
176	            sv += 1.0 - smoothstep(0.015 * zt, 0.04 * zt + 0.05, zf - zt);
177	          }
178	          vis = mix(vis, smoothstep(0.0, 1.0, sv / 25.0), mv);
179	        }
180	      }
181	      // m08occ: what the approved view could not see behind the towel / platform comes from the occlusion plate (the
182	      // painted door / window continued), not from the fallback tile with its straight edges; off the viewpoint only
183	      vec3 base = pc;
184	      if (uOccOn > 0.5) {
185	        vec4 oc = texture2D(uOcc, uv);
186	        base = mix(pc, oc.rgb, oc.a * smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
187	      }
188	      t = mix(base, texture2D(uPlate, uv).rgb, vis * keep);
189	      pw = vis * keep;
190	    }
191	  }
192	  // m08cup: the cups are round (rotationally symmetric), so a cup point the approved view could not see (its top hidden
193	  // behind the gold arch, or its outer part beyond the picture's edge) takes the painted pixels of its mirror point
194	  // across the vertical plane through the cup axis and the projector; off the approved viewpoint only
195	  if (uCup.w > 0.5) {
196	    float mc = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
197	    vec3 wm = vW - 2.0 * dot(vW - uCup.xyz, uCupM) * uCupM;
198	    vec4 pm = uProjVP * vec4(wm, 1.0);
199	    if (mc > 0.0 && pw < 0.999 && pm.w > 0.0) {
200	      vec3 nd = pm.xyz / pm.w;
201	      vec2 um = nd.xy * 0.5 + 0.5;
202	      if (um.x >= 0.0 && um.x <= 1.0 && um.y >= 0.0 && um.y <= 1.0) {
203	        float zf = linZ(nd.z * 0.5 + 0.5), zs = linZ(texture2D(uDepth, um).r);
204	        float vm = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
205	        t = mix(t, texture2D(uPlate, um).rgb, vm * (1.0 - pw) * mc);
206	      }
207	    }
208	  }
209	  // m08near: where the moving camera sees the floor projection magnified (it shows plate pixels the approved view saw far
210	  // away and small: smeared streaks), the crisp painted near river takes over, world-anchored along the painted river
211	  // (lateral = position across the swim lane, banks on the painted foam fringe; along = repeating with z). Off the
212	  // approved viewpoint only (approved view unchanged).
213	  if (uNear.w > 0.5) {
214	    // (measured on the plain projection: the swim remap is piecewise, its kinks would make the hand-over jump)
215	    vec2 pu = vProj.xy / max(vProj.w, 1e-4) * 0.5 * uPjRes;
216	    float det = abs(dFdx(pu).x * dFdy(pu).y - dFdx(pu).y * dFdy(pu).x);
217	    float mag = vProj.w > 0.0 ? inversesqrt(max(det, 1e-8)) : 99.0;
218	    float mn = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
219	    vec2 r = riv(vW.z);
220	    float hp = 0.5 * r.y, h = mix(hp, max(hp, uRivZ.z), mn);
221	    float sl = (vW.x - r.x) / h;
222	    vec2 tuv = vec2(0.5 + (uNearC.x + uNearC.y * sl) / (2.0 * uNear.z), (uNear.x - vW.z) / uNear.y);
223	    float wn = mn * smoothstep(uNearM.x, uNearM.y, mag) * (1.0 - smoothstep(uNearM.z, uNearM.w, abs(sl)));
224	    if (wn > 0.0) t = mix(t, texture2D(uNearT, tuv).rgb, wn);
225	  }
226	  gl_FragColor = vec4(pjInverse(t), 1.0);
227	}`;
