if (uCup.w > 0.5) {
  float mc = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
  // candidates: the mirror point first, then the same point turned about the cup axis (+-45, +-90 deg) where the mirror
  // point is hidden as well (the upper-right cup's top lies behind the arch's inner edge on both sides of the axis)
  float acc = pw;
  for (int k = 0; k < 5; k++) {
    if (mc <= 0.0 || acc >= 0.999) break;
    vec3 wm;
    if (k == 0) wm = vW - 2.0 * dot(vW - uCup.xyz, uCupM) * uCupM;
    else {
      float ang = (k < 3 ? 0.785398 : 1.570796) * (mod(float(k), 2.0) < 0.5 ? -1.0 : 1.0);
      vec3 d = vW - uCup.xyz; float ca = cos(ang), sa = sin(ang);
      wm = uCup.xyz + vec3(ca * d.x - sa * d.z, d.y, sa * d.x + ca * d.z);
    }
    vec4 pm = uProjVP * vec4(wm, 1.0);
    if (pm.w <= 0.0) continue;
    vec3 nd = pm.xyz / pm.w;
    vec2 um = nd.xy * 0.5 + 0.5;
    if (um.x < 0.0 || um.x > 1.0 || um.y < 0.0 || um.y > 1.0) continue;
    float zf = linZ(nd.z * 0.5 + 0.5), zs = linZ(texture2D(uDepth, um).r);
    float vm = (1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs)) * (1.0 - acc);
    t = mix(t, texture2D(uPlate, um).rgb, vm * mc);
    acc += vm;
  }
}

